/* CONTAINER QUE RECEBE O BRILHO */
.container-brilho{
  position: relative;
  overflow: hidden;
}

/* FAIXA DE BRILHO */
.container-brilho::before{
  content: "";
  position: absolute;
  top: 0;
  left: -30%;
  width: 120px; /* pode ajustar */
  height: 100%;
  background: #ffffff;
  box-shadow: 0 0 30px 20px rgba(255,255,255,0.6);
  transform: skewX(-20deg);
  opacity: 0;
  mix-blend-mode: plus-lighter;
  pointer-events: none;
  z-index: 2;

  animation: brilho-container 5s linear infinite;
}

/* ANIMAÇÃO */
@keyframes brilho-container{
  0%{
    left: -30%;
    opacity: 0;
  }
  30%{
    opacity: 0.25;
  }
  50%{
    opacity: 0.4;
  }
  70%{
    opacity: 0.25;
  }
  100%{
    left: 130%;
    opacity: 0;
  }
}

