.card {
  border-radius: 67px;
background: rgba(217, 217, 217, 0.04);
box-shadow: 0 4px 70.6px 18px rgba(255, 255, 255, 0.12) inset;
}

.card::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 67px;
  padding: 2px;
  background: linear-gradient(
    135deg, 
    #FFFFFF 0%,      /* Branco no topo esquerdo */
    #99999910 100%     /* Cinza no canto inferior direito */
  );
  -webkit-mask: 
    linear-gradient(#fff 0 0) content-box, 
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

@media(max-width:800px){
    .card {
  border-radius: 27px;
background: rgba(217, 217, 217, 0.04);
box-shadow: 0 4px 70.6px 18px rgba(255, 255, 255, 0.12) inset;
}

.card::before {
  content: '';
  position: absolute;
  inset: 0;
  border-radius: 27px;
  padding: 2px;
  background: linear-gradient(
    135deg, 
    #FFFFFF 0%,      /* Branco no topo esquerdo */
    #99999910 100%     /* Cinza no canto inferior direito */
  );
  -webkit-mask: 
    linear-gradient(#fff 0 0) content-box, 
    linear-gradient(#fff 0 0);
  -webkit-mask-composite: xor;
  mask-composite: exclude;
  pointer-events: none;
}

}

/* Animação de pulse com brightness - um por vez */
@keyframes card-pulse {
    0% {
        transform: scale(1);
        filter: brightness(1);
    }
    2% {
        transform: scale(1.05);
        filter: brightness(1.5);
    }
    14% {
        transform: scale(1.05);
        filter: brightness(1.15);
    }
    16%, 100% {
        transform: scale(1);
        filter: brightness(1);
    }
}

/* Aplicar a animação em cada card */
.card-pulse {
    animation: card-pulse 18s ease-in-out infinite;
}

/* Container de cima - cards 1, 2, 3 */
.container-cima .card-pulse:nth-child(1) {
    animation-delay: 0s;
}

.container-cima .card-pulse:nth-child(2) {
    animation-delay: 3s;
}

.container-cima .card-pulse:nth-child(3) {
    animation-delay: 6s;
}

/* Container de baixo - cards 4, 5, 6 */
.container-baixo .card-pulse:nth-child(1) {
    animation-delay: 9s;
}

.container-baixo .card-pulse:nth-child(2) {
    animation-delay: 12s;
}

.container-baixo .card-pulse:nth-child(3) {
    animation-delay: 15s;
}

